def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """
    Check if any two numbers in the list are closer to each other than the given threshold.

    Parameters:
    numbers (List[float]): Sequence of numeric values to examine.
    threshold (float): Minimum allowed distance between any two numbers.

    Returns:
    bool: True if a pair of numbers exists with an absolute difference less than threshold,
          otherwise False.

    Raises:
    TypeError: If 'numbers' is not a sequence of comparable elements or if 'threshold'
               is not a number.
    ValueError: If 'threshold' is negative.
    """
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a sequence such as list or tuple")
    if not isinstance(threshold, (int, float)):
        raise TypeError("threshold must be a numeric value")
    if threshold < 0:
        raise ValueError("threshold must be non‑negative")

    if len(numbers) < 2:
        return False

    try:
        sorted_numbers = sorted(numbers)
    except TypeError as exc:
        raise TypeError("All elements in numbers must be comparable") from exc

    for i in range(1, len(sorted_numbers)):
        if abs(sorted_numbers[i] - sorted_numbers[i - 1]) < threshold:
            return True
    return False

