        x, y = point
    except Exception as exc:
        raise ValueError("point must be a tuple of two integers") from exc

    if not (isinstance(n, int) and n >= 0):
        raise ValueError("n must be a non‑negative integer")

    if len(carpets) != n:
        raise ValueError("length of carpets list must equal n")

    top_index = -1  # default if no carpet covers the point

    for idx, carpet in enumerate(carpets, start=1):
        try:
            a, b, g, k = carpet
        except Exception:
            raise ValueError(f"Carpet at position {idx} must have four integers") from None

        # Check if the point lies within the rectangle (inclusive bounds)
        if a <= x <= a + g and b <= y <= b + k:
