    return top_index

def max_value_on_paths(N, grid_values):
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.

    Args:
    - N (int): The size of the grid (N x N).
    - grid_values (List[Tuple[int, int, int]]): A list of tuples where each tuple contains
      the x-coordinate, y-coordinate, and value to be placed on the grid at that position.
      The list is terminated by a tuple with all zeros.

    Returns:
    - int: The maximum sum of values collected on the two paths.
    """
    # Build a dictionary for grid values (1-indexed coordinates)
    grid = {}
    for x, y, v in grid_values:
        if x == 0 and y == 0 and v == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[(x, y)] = v

    # Helper for infinity
    NEG_INF = -10**15

    # dp_prev[i1][i2] represents the max sum when at step s-1
    # with person1 at (i1, j1) and person2 at (i2, j2)
    dp_prev = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    dp_prev[1][1] = grid.get((1, 1), 0)

    # Iterate over steps s = i1 + j1, starting from 3 up to 2*N (inclusive)
    for step in range(3, 2 * N + 1):
        dp_cur = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        # row ranges for walker1 and walker2
        i_min = max(1, step - N)
        i_max = min(N, step - 1)
        for i1 in range(i_min, i_max + 1):
            j1 = step - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = step - i2
                if j2 < 1 or j2 > N:
                    continue
                # Value collected at this step
                cell_value = grid.get((i1, j1), 0)
                if (i1, j1) != (i2, j2):
                    cell_value += grid.get((i2, j2), 0)
                # Consider all transitions from previous step
                best_prev = NEG_INF
                for pi1 in (i1 - 1, i1):
                    if pi1 < 1 or pi1 > N:
                        continue
                    pj1 = (step - 1) - pi1
                    if pj1 < 1 or pj1 > N:
                        continue
                    for pi2 in (i2 - 1, i2):
                        if pi2 < 1 or pi2 > N:
                            continue
                        pj2 = (step - 1) - pi2
                        if pj2 < 1 or pj2 > N:
                            continue
                        prev_val = dp_prev[pi1][pi2]
                        if prev_val > NEG_INF // 2:
                            best_prev = max(best_prev, prev_val)
                if best_prev > NEG_INF // 2:
                    dp_cur[i1][i2] = best_prev + cell_value
        dp_prev = dp_cur

    return dp_prev[N][N] if dp_prev[N][N] > NEG_INF // 2 else 0

