def count_passing_ways(n: int, m: int) -> int:
    if m < 0:
        raise ValueError("Number of passes m must be non-negative")
    if n <= 0:
        raise ValueError("Number of students n must be positive")
    # Base case: no passes, ball is already at the starting student
    if m == 0:
        return 1
    # Initialize DP arrays
    dp_curr = [0] * n
    dp_curr[0] = 1  # start at student 0
    for _ in range(m):
        dp_next = [0] * n
        for v in range(n):
            left = (v - 1) % n
            right = (v + 1) % n
            if left == right:  # handles n == 1 or n == 2
                dp_next[v] += dp_curr[left]
            else:
                dp_next[v] = dp_curr[left] + dp_curr[right]
        dp_curr = dp_next
    return dp_curr[0]

