def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of ordered pairs (P, Q) of positive integers such that
    gcd(P, Q) == x0 and lcm(P, Q) == y0.
    """
    # Basic validation
    if x0 <= 0 or y0 <= 0:
        return 0
    if y0 % x0 != 0:
        return 0

    # Helper function to compute GCD
    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    m = y0 // x0          # we need a * b = m with gcd(a, b) == 1
    count = 0
    i = 1
    while i * i <= m:
        if m % i == 0:
            a = i
            b = m // i
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1          # (P, Q) == (Q, P)
                else:
                    count += 2          # both (P, Q) and (Q, P)
        i += 1
    return count

def preorder_traversal(inorder: str, postorder: str) -> str:
    """Reconstruct a binary tree from inorder and postorder traversals
    and return its preorder traversal as a string.
    """
    if not inorder:
        return ''
    if len(inorder) != len(postorder):
        raise ValueError("Inorder and postorder strings must be of equal length.")
    # Map each value to its index in inorder for O(1) lookups
    index_map = {ch: i for i, ch in enumerate(inorder)}
    for ch in postorder:
        if ch not in index_map:
            raise ValueError(f"Character '{ch}' in postorder not found in inorder.")
    def build(pre_start: int, pre_end: int, in_start: int, in_end: int) -> str:
        if pre_start > pre_end or in_start > in_end:
            return ''
        root = postorder[pre_end]
        root_idx = index_map[root]
        # Number of nodes in left subtree
        left_size = root_idx - in_start
        left_pre = build(pre_start, pre_start + left_size - 1,
                         in_start, root_idx - 1)
        right_pre = build(pre_start + left_size, pre_end - 1,
                          root_idx + 1, in_end)
        return root + left_pre + right_pre
    return build(0, len(postorder) - 1, 0, len(inorder) - 1)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    If A can be transformed into B within 10 steps, return the minimum number of steps;
    otherwise return "NO ANSWER!".
    """
    try:
        from collections import deque
        from typing import Union
    except Exception:
        # If typing is not available, just proceed without type hints
        pass

    if A == B:
        return 0

    max_steps = 10
    visited = {A: 0}
    queue = deque([(A, 0)])

    while queue:
        current, depth = queue.popleft()
        if depth >= max_steps:
            continue

        next_depth = depth + 1
        for src, tgt in rules:
            start = 0
            # Find all occurrences of src in current string
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return next_depth
                if new_str not in visited or visited[new_str] > next_depth:
                    visited[new_str] = next_depth
                    queue.append((new_str, next_depth))
                start = idx + 1  # Move past this index to find next occurrence
    return "NO ANSWER!"

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    import re

    scenario_upper = scenario.upper()
    # Upper-case all names in liar_count for consistent comparison
    liars_upper = {name.upper() for name in liar_count}
    days_upper = {day.upper() for day in days_of_week}

    for speaker, stmts in statements.items():
        speaker_upper = speaker.upper()
        for stmt in stmts or []:
            # Skip statements that mention any day of the week
            if any(day in stmt.upper() for day in days_upper):
                continue

            stmt = stmt.strip()
            truth = None

            # Check "I am guilty." / "I am not guilty."
            if re.search(r"(?i)^I\s+am\s+guilty\.", stmt):
                truth = (speaker_upper == scenario_upper)
            elif re.search(r"(?i)^I\s+am\s+not\s+guilty\.", stmt):
                truth = (speaker_upper != scenario_upper)
            else:
                # Check "<NAME> is guilty." / "<NAME> is not guilty."
                match = re.search(r"(?i)^(\w+)\s+is\s+guilty\.", stmt)
                if match:
                    name_upper = match.group(1).upper()
                    truth = (name_upper == scenario_upper)
                else:
                    match = re.search(r"(?i)^(\w+)\s+is\s+not\s+guilty\.", stmt)
                    if match:
                        name_upper = match.group(1).upper()
                        truth = (name_upper != scenario_upper)

            # If statement doesn't pertain to guilt, ignore it
            if truth is None:
                continue

            # Verify consistency with liar status
            is_liar = speaker_upper in liars_upper
            if is_liar:
                if truth:
                    return False  # liar told a true statement
            else:
                if not truth:
                    return False  # truth teller made a false statement

    return True

