                # "<NAME> is guilty." or "<NAME> is not guilty."
                parts = stmt_clean.split()
                if len(parts) >= 3 and parts[1] == 'is':
                    name = parts[0].upper()
                    if parts[2] == 'guilty':
                        truth = (name == scenario_name)
                    elif parts[2] == 'not' and len(parts) >= 4 and parts[3] == 'guilty':
                        truth = (name != scenario_name)
            # If statement pattern is unknown, ignore it
            if truth is None:
                continue

            # Validate truthfulness against liar status
            if is_liar and truth is True:
                return False          # liars must lie (statement should be false)
            if not is_liar and truth is False:
                return False          # non-liars must tell truth
    return True

