def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.
    """
    # Normalize names for easy comparison
    all_names = set(statements.keys()) | {scenario}
    scenario = scenario.upper()
    liar_set = {name.upper() for name in liar_count}
    # Helper function to determine if a statement is true under the scenario
    def is_statement_true(speaker: str, stmt: str) -> bool:
        stmt = stmt.strip()
        stmt_lower = stmt.lower()
        # Skip statements about the day of the week
        for day in days_of_week:
            if day.lower() in stmt_lower:
                return True  # day statements are ignored, considered always true
        # Must contain the word "guilty" to be evaluated
        if "guilty" not in stmt_lower:
            return True
        # Determine subject of the statement
        if stmt_lower.startswith("i am"):
            subject = speaker.upper()
        else:
            # look for a name before the word "is"
            words = stmt_lower.replace(".", "").replace(",", "").split()
            subject = None
            for i, w in enumerate(words):
                raw = w.strip(".,;:")
                if raw.upper() in all_names:
                    subject = raw.upper()
                    break
            if subject is None:
                return True  # cannot parse, ignore
        # Determine if statement claims guilty or not guilty
        is_not = "not" in stmt_lower
        claim_guilty = not is_not
        # True if the claim matches the scenario
        return (scenario == subject) == claim_guilty

    for speaker, stmts in statements.items():
        speaker = speaker.upper()
        for stmt in stmts:
            # If speaker is a liar, statement must be false
            statement_truth = is_statement_true(speaker, stmt)
            if speaker in liar_set:
                if statement_truth:  # liar made a true statement
                    return False
            else:
                if not statement_truth:  # truthful participant made a false statement
                    return False
    return True

def count_apples_reachable(apple_heights: list, tao_reach: int) -> int:
    """
    Calculate the number of apples that Tao Tao can reach.

    Args:
        apple_heights (List[int]): The heights of apples from the ground (in centimeters).
        tao_reach (int): The maximum height Tao Tao can reach with her hand stretched upwards (in centimeters).

    Returns:
        int: The number of apples Tao Tao can reach with or without standing on a 30cm stool.
    """
    if not isinstance(apple_heights, list) or not isinstance(tao_reach, (int, float)):
        return 0
    try:
        effective_reach = tao_reach + 30  # Stroke adds an extra 30cm
        count = 0
        for h in apple_heights:
            try:
                if h <= effective_reach:
                    count += 1
            except Exception:
                # Skip values that are not comparable (e.g., None, strings)
                continue
        return count
    except Exception:
        return 0

def remaining_trees_after_clearing(l, areas):
    if l <= 0:
        return 0
    # Sort intervals by start
    sorted_areas = sorted([(min(start, end), max(start, end)) for start, end in areas])
    merged = []
    for start, end in sorted_areas:
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)
    total_removed = sum(end - start for start, end in merged)
    remaining = l - total_removed
    return remaining if remaining > 0 else 0

def max_herb_value(T, M, herbs):
    """
    Calculates the maximum total value of herbs that can be picked within a given time limit.

    :param T: Total time available for picking herbs.
    :param M: Number of different herbs in the cave.
    :param herbs: List of tuples where each tuple contains (time_required, value).
    :return: Maximum total value achievable without exceeding the time limit.
    """
    # Basic validation
    if T <= 0 or not herbs:
        return 0

    # Filter out impossible or useless herbs (time <= 0, value <= 0 or time > T)
    filtered = []
    for time, value in herbs:
        if time <= 0 or value <= 0 or time > T:
            continue
        filtered.append((time, value))

    if not filtered:
        return 0

    # One‑dimensional DP array: dp[cap] = max value with total time cap
    dp = [0] * (T + 1)

    for time, value in filtered:
        # Iterate backwards to avoid using the same item multiple times
        for cap in range(T, time - 1, -1):
            new_val = dp[cap - time] + value
            if new_val > dp[cap]:
                dp[cap] = new_val

    return max(dp)

