    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (list of int): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    try:
        if not isinstance(heights, list):
            raise TypeError("heights must be a list")
        n = len(heights)
        if n <= 1:
            return 0

        # Compute Longest Increasing Subsequence (LIS) lengths ending at each index
        lis = [1] * n
        for i in range(n):
            for j in range(i):
                if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                    lis[i] = lis[j] + 1

        # Compute Longest Decreasing Subsequence (LDS) lengths starting at each index
        lds = [1] * n
        for i in range(n - 1, -1, -1):
            for j in range(i + 1, n):
                if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                    lds[i] = lds[j] + 1

        # Find maximum length of a bitonic subsequence
        max_bitonic = 0
        for i in range(n):
            current = lis[i] + lds[i] - 1
            if current > max_bitonic:
                max_bitonic = current

        # The minimum number to leave is the total students minus the longest bitonic subsequence
        return n - max_bitonic

    except Exception as e:
        # In case of unexpected errors, return 0 as a safe default
        return 0

