    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i]:
                lis[i] = max(lis[i], lis[j] + 1)

    # Longest decreasing subsequence length starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i]:
                lds[i] = max(lds[i], lds[j] + 1)

    # Maximum length of a bitonic subsequence (increase then decrease)
    max_len = 0
    for i in range(n):
        # subtract 1 because the peak student is counted twice
        max_len = max(max_len, lis[i] + lds[i] - 1)

