    return n - max_len

def sort_students(student_scores):
    """
    Sorts a list of students based on their scores. The students are sorted primarily by their total score (descending),
    then by their Chinese score (descending), and finally by their student number (ascending) in case of a tie.

    Args:
    student_scores (list): A list of tuples, where each tuple consists of (student_number, total_score, Chinese_score).

    Returns:
    list: A list of tuples sorted according to the above rules.
    """
    # Validate input
    if not isinstance(student_scores, (list, tuple)):
        raise TypeError("student_scores must be a list or tuple of student records.")

    for record in student_scores:
        if not isinstance(record, (list, tuple)):
            raise TypeError("Each student record must be a tuple or list.")
        if len(record) != 3:
            raise ValueError("Each student record must contain exactly three elements: (student_number, total_score, Chinese_score).")
        for value in record:
            if not isinstance(value, int):
                raise TypeError("All elements in a student record must be integers.")

    # Sort using a key that prioritizes total_score descending, Chinese_score descending, then student_number ascending
    sorted_students = sorted(
        student_scores,
        key=lambda x: (-x[1], -x[2], x[0])
    )
    return sorted_students
